# Hero Entry Animation — CSS Scroll-Driven + Motion fallback

**Estratégia:** CSS nativo primeiro (`@keyframes` + `animation-timeline: view()`) — zero JS, zero deps. Para browsers sem suporte, `IntersectionObserver` como fallback limpo.

```tsx
// HeroSection.tsx
import { useEffect, useRef } from "react";

/* ─── tipos ─────────────────────────────────────────────── */
interface HeroSectionProps {
  headline: string;
  subline: string;
  cta: string;
}

/* ─── hook: IntersectionObserver fallback ────────────────── */
function useEnterAnimation(ref: React.RefObject<HTMLElement | null>) {
  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    /* Se o browser suporta animation-timeline: view() não precisamos de JS */
    const supportsScrollTimeline =
      CSS.supports("animation-timeline", "view()");
    if (supportsScrollTimeline) return;

    /* Fallback: IntersectionObserver */
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          el.dataset.visible = "true";
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);
}

/* ─── componente ─────────────────────────────────────────── */
export function HeroSection({ headline, subline, cta }: HeroSectionProps) {
  const heroRef = useRef<HTMLElement>(null);
  useEnterAnimation(heroRef);

  return (
    <>
      <style>{heroStyles}</style>

      <section ref={heroRef} className="hero" aria-label="Hero">
        <div className="hero__content">
          <h1 className="hero__headline animate-item" style={{ "--i": 0 } as React.CSSProperties}>
            {headline}
          </h1>
          <p className="hero__subline animate-item" style={{ "--i": 1 } as React.CSSProperties}>
            {subline}
          </p>
          <a href="#start" className="hero__cta animate-item" style={{ "--i": 2 } as React.CSSProperties}>
            {cta}
          </a>
        </div>
      </section>
    </>
  );
}

/* ─── estilos ────────────────────────────────────────────── */
const heroStyles = `
  /* ── reset de movimento ── */
  @media (prefers-reduced-motion: reduce) {
    .animate-item {
      animation: none !important;
      opacity: 1 !important;
      transform: none !important;
    }
  }

  /* ── keyframe base ── */
  @keyframes fadeSlideUp {
    from {
      opacity: 0;
      transform: translateY(28px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* ── estado inicial (escondido até animar) ── */
  .animate-item {
    opacity: 0;
    transform: translateY(28px);
    will-change: opacity, transform;
  }

  /* ── PATH A: CSS scroll-driven nativo ── */
  @supports (animation-timeline: view()) {
