# Hero Animation — Fade + Slide com Intersection Observer

Sem libs externas. Só React + CSS custom properties.

## Hook reutilizável

```typescript
// hooks/useInView.ts
import { useEffect, useRef, useState } from "react";

interface UseInViewOptions {
  threshold?: number;
  rootMargin?: string;
  once?: boolean;
}

export function useInView<T extends Element = Element>({
  threshold = 0.1,
  rootMargin = "0px",
  once = true,
}: UseInViewOptions = {}) {
  const ref = useRef<T>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          if (once) observer.disconnect();
        } else if (!once) {
          setInView(false);
        }
      },
      { threshold, rootMargin }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [threshold, rootMargin, once]);

  return { ref, inView };
}
```

## Componente de animação genérico

```typescript
// components/Reveal.tsx
import { CSSProperties, ReactNode } from "react";
import { useInView } from "@/hooks/useInView";

type Direction = "up" | "down" | "left" | "right";

interface RevealProps {
  children: ReactNode;
  direction?: Direction;
  distance?: number;
  duration?: number;
  delay?: number;
  easing?: string;
  className?: string;
}

const TRANSLATE: Record<Direction, string> = {
  up:    "0, 32px, 0",
  down:  "0, -32px, 0",
  left:  "32px, 0, 0",
  right: "-32px, 0, 0",
};

export function Reveal({
  children,
  direction = "up",
  distance = 32,
  duration = 700,
  delay = 0,
  easing = "cubic-bezier(0.22, 1, 0.36, 1)", // ease-out-expo
  className,
}: RevealProps) {
  const { ref, inView } = useInView<HTMLDivElement>({ threshold: 0.15 });

  // Recalcula translate com distance dinâmica
  const translateMap: Record<Direction, string> = {
    up:    `0, ${distance}px, 0`,
    down:  `0, -${distance}px, 0`,
    left:  `${distance}px, 0, 0`,
    right: `-${distance}px, 0, 0`,
  };

  const style: CSSProperties = {
    opacity: inView ? 1 : 0,
    transform: inView
      ? "translate3d(0, 0, 0)"
      : `translate3d(${translateMap[direction]})`,
    transition: `opacity ${duration}ms ${easing} ${delay}ms,
                 transform ${duration}ms ${easing} ${delay}ms`,
    willChange: "opacity, transform",
  };

  return (
    <div ref={ref} style={style} className={className}>
      {children}
    </div>
  );
}
