  }
  db.query(
    'SELECT id, username, created_at FROM users WHERE id = ?',
    [id],
    (e, rows) => {
      if (e) { logger.error({ err: e, id }, 'user lookup failed'); return res.status(500).json({ error: 'internal' }); }
      if (!rows || rows.length === 0) return res.status(404).json({ error: 'not found' });
      res.json(rows[0]);
    }
  );
});
```

## Auditoria de Segurança

### 🚨 Problemas Encontrados

---

#### 1. **SQL Injection** (Crítico)
O problema principal — concatenas input do utilizador diretamente na query.

```js
// ❌ Isto permite ataques como:
// GET /user?id=1 OR 1=1          → devolve TODOS os utilizadores
// GET /user?id=1; DROP TABLE users → pode destruir a BD
// GET /user?id=1 UNION SELECT password,2 FROM admins

db.query("SELECT * FROM users WHERE id = " + id, ...)
```

---

#### 2. **Ausência de validação de input** (Alto)
`id` pode ser `undefined`, uma string vazia, ou qualquer coisa.

```js
// GET /user        → id é undefined → query inválida
// GET /user?id=abc → string na query → comportamento inesperado
```

---

#### 3. **Exposição excessiva de dados** (Médio)
`SELECT *` devolve **todas as colunas**, incluindo potencialmente `password_hash`, `tokens`, etc.

---

#### 4. **Sem tratamento de erros** (Médio)
O erro `e` é ignorado silenciosamente — pode expor stack traces ou crashar.

```js
(e, rows) => res.json(rows)  // ← e nunca é verificado
```

---

### ✅ Versão Corrigida

```js
app.get('/user', (req, res) => {
  const id = req.query.id;

  // 1. Validar: deve existir e ser inteiro positivo
  const parsed = parseInt(id, 10);
  if (!id || isNaN(parsed) || parsed <= 0) {
    return res.status(400).json({ error: 'ID inválido.' });
  }

  // 2. Query parametrizada — nunca concatenar input
  const sql = 'SELECT id, name, email FROM users WHERE id = ?';

  db.query(sql, [parsed], (err, rows) => {
    // 3. Tratar erros sem expor detalhes internos
    if (err) {
      console.error('Erro na query:', err); // log interno
      return res.status(500).json({ error: 'Erro interno.' });
    }

    // 4. Verificar se o recurso existe
    if (rows.length === 0) {
      return res.status(404).json({ error: 'Utilizador não encontrado.' });
    }

    res.json(rows[0]);
  });
});
```

---

### Resumo das Correções

| Problema | Correção |
|---|---|
| SQL Injection | Query parametrizada com `?` e `[parsed]` |
| Input inválido | `parseInt` + validação explícita |
| Exposição de dados | Colunas explícitas em vez de `SELECT *` |
| Erros ignorados | Verificação de `err` com resposta adequada |

---

### 💡 Consideração Adicional

Se usares um **query builder** como [Knex.js](https://knexjs.org/) ou um ORM como [Prisma](https://www.prisma.io/), a parametrização é automática e reduz a superfície de erro humano.

# Auditoria do handler

## Problemas

### 1. SQL Injection (crítico)
A concatenação direta de `req.query.id` na string SQL permite injeção. Um pedido como:

```
GET /user?id=1 OR 1=1
GET /user?id=1; DROP TABLE users;--
```

…executa SQL arbitrário. Este é o problema central e é grave.

### 2. Sem validação/tipagem do input
`req.query.id` pode ser `undefined`, uma string qualquer, um array (`?id=1&id=2` → `['1','2']`) ou um objeto (`?id[$gt]=`). Nunca assumas que é um número.

### 3. Sem tratamento de erros
Se `db.query` falhar, `e` é ignorado e `res.json(rows)` envia `undefined`. O cliente fica sem resposta significativa e tu sem log.

### 4. Fuga de dados
`SELECT *` devolve todas as colunas — incluindo potencialmente hashes de password, tokens, emails internos, etc. Devolve apenas o que o endpoint precisa.

### 5. Sem autenticação/autorização
Qualquer pessoa pode consultar qualquer utilizador pelo id. Tipicamente queres exigir auth e verificar se o requester pode ver aquele user.

### 6. Sem rate limiting
Endpoint público que faz query à BD — alvo fácil para enumeração/DoS.

---

## Versão corrigida

```js
app.get('/user',
  requireAuth,                    // middleware de autenticação
  rateLimiter,                    // ex.: express-rate-limit
  async (req, res) => {
    // 1. Validar e converter o input
    const id = Number.parseInt(req.query.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid id' });
    }

    // 2. (Opcional) autorização: o user só se vê a si próprio?
    // if (req.user.id !== id && !req.user.isAdmin) {
    //   return res.status(403).json({ error: 'forbidden' });
    // }

    try {
      // 3. Query parametrizada + colunas explícitas
      const rows = await db.query(
        'SELECT id, name, email FROM users WHERE id = ? LIMIT 1',
        [id]
      );

      if (!rows.length) {
        return res.status(404).json({ error: 'not found' });
      }
      return res.json(rows[0]);
    } catch (err) {
      req.log?.error({ err }, 'db error /user');
      return res.status(500).json({ error: 'internal error' });
    }
  }
);
```

## Pontos-chave

- **Placeholders (`?` ou `$1`)** em vez de concatenação — resolve a SQL injection de raiz.
- **Validação explícita** do tipo antes de tocar na BD.
- **Colunas explícitas** em vez de `SELECT *`.
- **`LIMIT 1`** porque procuras um único registo por PK.
- **Try/catch** com log e resposta apropriada (não devolvas o erro cru ao cliente).
- **Auth + rate limit** ao nível do middleware.

Se usares Postgres (`pg`), a sintaxe do placeholder é `$1`; em `mysql2` é `?`. Confirma qual driver tens.

# Edge Functions no Vercel para Redirects por Geolocalização

## Visão Geral

As Edge Functions do Vercel têm acesso à geolocalização do utilizador através dos headers da request, permitindo redirects sem latência adicional.

---

## Estrutura do Projeto

```
my-app/
├── middleware.ts          # Edge Middleware (recomendado)
├── app/
│   ├── page.tsx
│   └── [locale]/
│       └── page.tsx
└── vercel.json
```

---

## Opção 1: Middleware (Recomendado)

### `middleware.ts`

```typescript
import { NextRequest, NextResponse } from 'next/server';

// Mapeamento de países para locales/regiões
const COUNTRY_REDIRECTS: Record<string, string> = {
  PT: '/pt',
  BR: '/br',
  US: '/en',
  GB: '/en-gb',
  ES: '/es',
  FR: '/fr',
  DE: '/de',
};

// Países que redirecionam para página específica
const BLOCKED_COUNTRIES = ['KP', 'CU', 'IR'];

// Locale padrão
const DEFAULT_LOCALE = '/en';

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Ignorar assets estáticos e API routes
  if (
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api') ||
    pathname.startsWith('/static') ||
    pathname.includes('.')
  ) {
    return NextResponse.next();
  }

  // Obter dados de geolocalização dos headers do Vercel
  const country = request.geo?.country ?? 'US';
  const region = request.geo?.region ?? '';
  const city = request.geo?.city ?? '';

  console.log(`[Geo] Country: ${country}, Region: ${region}, City: ${city}`);

  // Verificar países bloqueados
  if (BLOCKED_COUNTRIES.includes(country)) {
    return NextResponse.redirect(new URL('/unavailable', request.url));
  }

  // Evitar redirect loop (já está no path correto)
  const alreadyRedirected = Object.values(COUNTRY_REDIRECTS).some((path) =>
    pathname.startsWith(path)
  );

  if (alreadyRedirected) {
    return NextResponse.next();
  }

  // Redirecionar apenas na raiz
  if (pathname === '/') {
    const redirectPath = COUNTRY_REDIRECTS[country] ?? DEFAULT_LOCALE;
    const url = request.nextUrl.clone();
    url.pathname = redirectPath;

    return NextResponse.redirect(url, {
      status: 307, // Temporary redirect
    });
  }

  return NextResponse.next();
}

export const config = {
  matcher: [
    /*
     * Executar em todos os paths exceto:
     * - _next/static
     * - _next/image
     * - favicon.ico
     */
    '/((?!_next/static|_next/image|favicon.ico).*)',
  ],
};
```

---

## Opção 2: Lógica Avançada com Regiões

### `middleware.ts` (versão avançada)

```typescript
import { NextRequest, NextResponse } from 'next/server';

interface GeoConfig {
  locale: string;
  currency: string;
  timezone: string;
}

const GEO_CONFIG: Record<string, GeoConfig> = {
  PT: { locale: 'pt-PT', currency: 'EUR', timezone: 'Europe/Lisbon' },
  BR: { locale: 'pt-BR', currency: 'BRL', timezone: 'America/Sao_Paulo' },
  US: { locale: 'en-US', currency: 'USD', timezone: 'America/New_York' },
  GB: { locale: 'en-GB', currency: 'GBP', timezone: 'Europe/London' },
  ES: { locale: 'es-ES', currency: 'EUR', timezone: 'Europe/Madrid' },
  JP: { locale: 'ja-JP', currency: 'JPY', timezone: 'Asia/Tokyo' },
};

const DEFAULT_CONFIG: GeoConfig = {
  locale: 'en-US',
  currency: 'USD',
  timezone: 'UTC',
};

// Regiões especiais dentro de um país
const REGION_OVERRIDES: Record<string, string> = {
  'US-CA': '/en-us/california', // California tem leis específicas (CCPA)
  'US-TX': '/en-us/texas',
  'CA-QC': '/fr-ca', // Quebec → Francês
};

export function middleware(request: NextRequest) {
  const { pathname, searchParams } = request.nextUrl;

  // Permitir override manual via query param ou cookie
  const localeOverride =
    searchParams.get('locale') || request.cookies.get('preferred-locale')?.value;

  if (localeOverride) {
    const response = NextResponse.next();
    // Salvar preferência em cookie
    response.cookies.set('preferred-locale', localeOverride, {
      maxAge: 60 * 60 * 24 * 365, // 1 ano
      path: '/',
    });
    return response;
  }

  // Dados de geolocalização
  const country = request.geo?.country ?? '';
  const region = request.geo?.region ?? '';
  const geoKey = `${country}-${region}`;

  // Verificar override por região
  if (REGION_OVERRIDES[geoKey] && pathname === '/') {
    return NextResponse.redirect(
      new URL(REGION_OVERRIDES[geoKey], request.url),
      { status: 307 }
    );
  }

  // Configuração baseada no país
  const geoConfig = GEO_CONFIG[country] ?? DEFAULT_CONFIG;

  // Adicionar headers com info de geo para uso no frontend
  const response = NextResponse.next();
  response.headers.set('x-user-country', country);
  response.headers.set('x-user-locale', geoConfig.locale);
  response.headers.set('x-user-currency', geoConfig.currency);
  response.headers.set('x-user-timezone', geoConfig.timezone);

  // Redirect para path localizado
  if (pathname === '/') {
    const localePath = `/${geoConfig.locale.toLowerCase()}`;
    return NextResponse.redirect(new URL(localePath, request.url), {
      status: 307,
      headers: response.headers,
    });
  }

  return response;
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico|api).*)'],
};
```

