  const hero      = document.getElementById('hero');
  let   rafId     = null;
  let   lastY     = -1;
  let   heroH     = hero.offsetHeight;

  // Resize: só actualiza a altura (sem reflow no rAF)
  const ro = new ResizeObserver(entries => {
    heroH = entries[0].contentRect.height;
