  ro.observe(hero);

  function applyParallax() {
    rafId = null;
    const scrollY = window.scrollY;

    // Só processa enquanto o hero está visível
    if (scrollY > heroH || scrollY === lastY) return;
    lastY = scrollY;

    // Batch: todas as leituras já feitas (scrollY), agora só writes
    for (const { el, speed } of layers) {
      // translateY negativo = move mais devagar que o scroll → efeito parallax
      el.style.transform = `translateY(${scrollY * speed}px)`;
