## JavaScript — RAF + throttle real

```js
class Parallax {
  constructor(selector) {
    this.layers = [...document.querySelectorAll(selector)];
    this.ticking = false;
    this.lastScrollY = 0;

    // Pré-lê os data-speed uma vez (evita reflow no loop)
    this.speeds = this.layers.map(el =>
      parseFloat(el.dataset.speed ?? 0.5)
    );

    this.init();
  }

  init() {
    // Passive: não bloqueia o scroll thread
    window.addEventListener('scroll', this.onScroll.bind(this), {
      passive: true
    });

    // Render inicial
    this.update();
  }

  onScroll() {
    this.lastScrollY = window.scrollY;

    // Throttle via RAF — só 1 frame por vez
    if (!this.ticking) {
      requestAnimationFrame(() => {
        this.update();
        this.ticking = false;
      });
      this.ticking = true;
    }
  }

  update() {
    const scrollY = this.lastScrollY;

    this.layers.forEach((layer, i) => {
      const speed  = this.speeds[i];
      const offset = -(scrollY * speed);

      // APENAS transform — zero layout thrashing
      layer.style.transform = `translate3d(0, ${offset}px, 0)`;
    });
  }

  // Cleanup quando sair da viewport (IntersectionObserver)
  destroy() {
    window.removeEventListener('scroll', this.onScroll);
  }
}

// Init
const parallax = new Parallax('[data-speed]');
```

