class Parallax {
  constructor(selector) {
    this.layers = [...document.querySelectorAll(selector)];
    this.speeds = this.layers.map(el => parseFloat(el.dataset.speed ?? 0.5));
    this.ticking = false;
    this.lastScrollY = 0;
    this.active = false;   // ← só roda se visível

    this.observeVisibility();
    this.init();
  }

  observeVisibility() {
    const hero = this.layers[0]?.closest('section');
    if (!hero) return;

    const io = new IntersectionObserver(([entry]) => {
      this.active = entry.isIntersecting;
    }, { threshold: 0 });

    io.observe(hero);
  }

  onScroll() {
    if (!this.active) return;   // ← skip se fora da tela
    this.lastScrollY = window.scrollY;

    if (!this.ticking) {
      requestAnimationFrame(() => {
        this.update();
        this.ticking = false;
      });
      this.ticking = true;
    }
  }

  // ... resto igual
}
