## Versão sem dependências (CSS puro + React)

```tsx
// CardPureCss.tsx — zero dependências externas
import { useRef, useState, CSSProperties } from "react";

interface TiltCardProps {
  title: string;
  value: string;
  icon: string;
  color: string;
}

export function TiltCard({ title, value, icon, color }: TiltCardProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const [hovered, setHovered] = useState(false);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = ref.current!.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const dx = (e.clientX - cx) / (rect.width / 2);   // -1 a 1
    const dy = (e.clientY - cy) / (rect.height / 2);  // -1 a 1
    setTilt({ x: dy * -6, y: dx * 6 });               // graus de rotação
  };

  const cardStyle: CSSProperties = {
    background: "#fff",
    borderRadius: "16px",
    padding: "24px",
    cursor: "pointer",
    border: "1px solid rgba(0,0,0,0.06)",
    transition: hovered
      ? "transform 0.08s linear, box-shadow 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)"
      : "transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.4s ease",
    transform: hovered
      ? `perspective(800px) rotateX(${tilt.x}deg) rotateY(${tilt.y}deg) scale(1.03) translateY(-4px)`
      : "perspective(800px) rotateX(0deg) rotateY(0deg) scale(1) translateY(0px)",
    boxShadow: hovered
      ? `0 20px 40px rgba(0,0,0,0.14), 0 4px 12px rgba(0,0,0,0.08), 0 0 0 1px ${color}20`
      : "0 2px 8px rgba(0,0,0,0.08)",
    willChange: "transform",
  };

  return (
    <div
      ref={ref}
      style={cardStyle}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => { setHovered(false); setTilt({ x: 0, y: 0 }); }}
    >
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <div>
          <p style={{ margin: 0, fontSize: "13px", color: "#94a3b8" }}>{title}</p>
          <h2 style={{ margin: "8px 0 0", fontSize: "28px", fontWeight: 700, color: "#0f172a" }}>
            {value}
          </h2>
        </div>
        <div
          style={{
            width: 48, height: 48,
            borderRadius: "12px",
            background: `${color}18`,
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: "22px",
            transition: "transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)",
            transform: hovered ? "scale(1.2) rotate(-8deg)" : "scale(1) rotate(0deg)",
          }}
        >
          {icon}
        </div>
      </div>
    </div>
  );
}
