/**
 * Orchestrated Stagger Sequence
 * ─────────────────────────────
 * Architecture:
 *   1. Register ScrollTrigger plugin
 *   2. Define per-element animation config (easing, from-state, duration)
 *   3. Build a master GSAP timeline (paused)
 *   4. Add each tween at a staggered position offset
 *   5. Attach ScrollTrigger with scrub + pin
 *   6. Hook progress callback → update debug bar
 */

gsap.registerPlugin(ScrollTrigger);

// ─── 1. Element Config ────────────────────────────────────────────────────────
//
// Each entry maps to a .card[data-index="n"]
// `from` defines the initial (hidden) state
// `ease` is unique per element — this is the key differentiator
// `duration` controls how long each element's tween lasts within the timeline
// `position` is the label/offset in the master timeline (stagger offset)

const ELEMENT_CONFIG = [
  {
    index: 0,
    ease: "power4.out",
    duration: 0.6,
    from: { opacity: 0, y: 80, scale: 0.85 },
    position: 0,          // starts at timeline t=0
  },
  {
    index: 1,
    ease: "elastic.out(1, 0.5)",
    duration: 0.9,        // elastic needs more time to settle
    from: { opacity: 0, y: 100, scale: 0.8, rotation: -8 },
    position: 0.08,       // starts 0.08s into timeline
  },
  {
    index: 2,
    ease: "back.out(2.5)",
    duration: 0.65,
    from: { opacity: 0, y: 60, scale: 0.7, rotation: 6 },
    position: 0.16,
  },
  {
    index: 3,
    ease: "circ.out",
    duration: 0.55,
    from: { opacity: 0, y: 90, x: -20, scale: 0.9 },
    position: 0.24,
  },
  {
    index: 4,
    ease: "expo.out",
    duration: 0.7,
    from: { opacity: 0, y: 70, scale: 0.75, rotation: -4 },
    position: 0.32,
  },
  {
    index: 5,
    ease: "bounce.out",
    duration: 0.85,       // bounce needs time for bounces to complete
    from: { opacity: 0, y: 120, scale: 0.9 },
    position: 0.40,
  },
];

// ─── 2. Cache DOM ─────────────────────────────────────────────────────────────

const cards = gsap.utils.toArray(".card");
const progressFill = document.getElementById("progress-fill");
const pinSection = document.getElementById("pin-section");

// ─── 3. Set Initial States ────────────────────────────────────────────────────
//
// Set via GSAP (not just CSS) so GSAP owns the state.
// Prevents any flash or conflict with CSS initial values.

ELEMENT_CONFIG.forEach(({ index, from }) => {
  gsap.set(cards[index], from);
});

// ─── 4. Build Master Timeline ─────────────────────────────────────────────────
//
// `paused: true` — ScrollTrigger will drive playback, not autoplay
// `defaults` apply to all tweens unless overridden

const masterTl = gsap.timeline({
  paused: true,
  defaults: {
    // No global ease — each tween defines its own
    clearProps: "rotation", // clean up rotation after animation
  },
  onUpdate() {
    // Update debug progress bar
    const progress = masterTl.progress();
    gsap.set(progressFill, { width: `${progress * 100}%` });
  },
});

// ─── 5. Add Tweens to Timeline ────────────────────────────────────────────────
//
// Each tween animates FROM its hidden state TO the natural/computed state.
// `gsap.to` with the `from` state already set via gsap.set above.
// We use `to` with the final (visible) values.

ELEMENT_CONFIG.forEach(({ index, ease, duration, position }) => {
  masterTl.to(
    cards[index],
    {
      opacity: 1,
      y: 0,
      x: 0,
      scale: 1,
      rotation: 0,
      ease,
      duration,
    },
    position  // ← stagger offset: when this tween starts in the timeline
  );
