### 1. JWT / Tokens
```javascript
// ❌ PROBLEMAS COMUNS
app.post('/login', async (req, res) => {
  const { email, password } = req.body

  // ❌ Sem rate limiting
  // ❌ Sem validação de formato antes de ir à DB
  // ❌ Comparação síncrona (timing attack)
  if (user.password === password) { ... }

  // ❌ Secret fraco / hardcoded
  const token = jwt.sign({ id: user.id }, 'secret123')

  // ❌ Sem expiração
  // ❌ Role/permissions não incluídas no payload de forma segura
})

// ✅ CORRETO
app.post('/login', rateLimiter, async (req, res) => {
  const { email, password } = req.body

  // Validar formato primeiro (não vai à DB com lixo)
  if (!isValidEmail(email) || !password?.trim()) {
    return res.status(400).json({ error: 'Invalid credentials' })
    // ⚠️ Mensagem genérica — não dizer "email não existe"
  }

  const user = await db.users.findOne({ email })

  // ✅ Comparação em tempo constante (evita timing attack)
  const valid = user && await bcrypt.compare(password, user.passwordHash)

  if (!valid) {
    await logFailedAttempt(email) // auditoria
    return res.status(401).json({ error: 'Invalid credentials' })
  }

  const token = jwt.sign(
    { sub: user.id, role: user.role },
    process.env.JWT_SECRET,   // ✅ env var
    { expiresIn: '15m' }      // ✅ curta duração
  )

  // ✅ Refresh token em httpOnly cookie
  res.cookie('refreshToken', refreshToken, {
    httpOnly: true,
    secure: true,
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000
  })

  res.json({ token })
})
