### 2. Middleware de Auth
```javascript
// ❌ PROBLEMAS COMUNS
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization  // ❌ sem split 'Bearer '

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET)
    next()
  } catch {
    next() // ❌ CRÍTICO: continua sem autenticar!
  }
}

// ✅ CORRETO
const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization

  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' })
  }

  const token = authHeader.split(' ')[1]

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'], // ✅ algoritmo explícito (evita 'none' attack)
    })

    // ✅ Verificar se token foi revogado (blacklist/Redis)
    const isRevoked = await tokenBlacklist.has(token)
    if (isRevoked) return res.status(401).json({ error: 'Unauthorized' })

    req.user = payload
    next()
  } catch (err) {
    return res.status(401).json({ error: 'Unauthorized' }) // ✅ não expõe detalhe
  }
}
