### 5. Mass Assignment
```javascript
// ❌ Aceita qualquer campo — utilizador pode enviar { role: 'admin' }
app.put('/profile', auth, async (req, res) => {
  await User.update(req.user.id, req.body) // ❌ PERIGO
})

// ✅ Whitelist explícita
app.put('/profile', auth, async (req, res) => {
  const allowed = ['name', 'bio', 'avatar']
  const updates = Object.fromEntries(
    Object.entries(req.body).filter(([k]) => allowed.includes(k))
  )
  await User.update(req.user.id, updates)
})
```

### 6. IDOR (Insecure Direct Object Reference)
```javascript
// ❌ Utilizador A acede a dados do utilizador B
app.get('/orders/:id', auth, async (req, res) => {
  const order = await Order.findById(req.params.id) // ❌ sem verificar dono
  res.json(order)
})

// ✅ Sempre filtrar pelo utilizador autenticado
app.get('/orders/:id', auth, async (req, res) => {
  const order = await Order.findOne({ 
    _id: req.params.id, 
    userId: req.user.sub  // ✅ garante que é dono
  })
  if (!order) return res.status(404).json({ error: 'Not found' })
  res.json(order)
})
```

