```typescript
// ─── token service ───────────────────────────────────────────────────────────

import jwt        from 'jsonwebtoken'
import crypto     from 'crypto'
import { db }     from './db'
import { redis }  from './redis'

const ACCESS_TOKEN_TTL  = 15 * 60          // 15 minutos (segundos)
const REFRESH_TOKEN_TTL = 7 * 24 * 60 * 60 // 7 dias (segundos)

export class TokenService {

  // ── gerar par de tokens ──────────────────────────────────────────────────

  async generateTokenPair(
    userId:   string,
    familyId: string | null = null  // null = nova família (login)
  ): Promise<{ accessToken: string; refreshToken: string }> {

    // JWT de curta duração — vai para memória do cliente
    const accessToken = jwt.sign(
      {
        sub:  userId,
        type: 'access',
        jti:  crypto.randomUUID(), // permite blacklist individual
      },
      process.env.JWT_SECRET!,
      { expiresIn: ACCESS_TOKEN_TTL }
    )

    // Refresh token — opaco, vai para HttpOnly cookie
    const refreshToken     = crypto.randomBytes(64).toString('hex')
    const refreshTokenHash = this.hash(refreshToken)
    const newFamilyId      = familyId ?? crypto.randomUUID()

    await db.tokenFamily.upsert({
      where: { familyId: newFamilyId },
      create: {
        familyId,
        userId,
        currentToken:   refreshTokenHash,
        previousTokens: [],
        expiresAt:      new Date(Date.now() + REFRESH_TOKEN_TTL * 1000),
        isCompromised:  false,
      },
      update: {
        // rotation: mover token actual para histórico
        previousTokens: { push: db.tokenFamily.fields.currentToken },
        currentToken:   refreshTokenHash,
        // NÃO renovar expiresAt — família tem vida máxima fixa
      }
    })

    return { accessToken, refreshToken }
  }

  // ── rotation com detecção de roubo ───────────────────────────────────────

  async rotateRefreshToken(
    incomingToken: string
  ): Promise<{ accessToken: string; refreshToken: string; userId: string }> {

    const incomingHash = this.hash(incomingToken)

    const family = await db.tokenFamily.findFirst({
      where: {
        OR: [
          { currentToken:   incomingHash },
          { previousTokens: { has: incomingHash } }
        ]
      }
    })

    // Token não existe de todo
    if (!family) {
      throw new AuthError('INVALID_TOKEN')
    }

    // ⚠️ DETECÇÃO DE ROUBO: token já foi usado anteriormente
    // Significa que alguém está a usar um token antigo
    // → ou o utilizador legítimo, ou o atacante
    // → não conseguimos saber quem é quem → invalidar TUDO
    if (family.previousTokens.includes(incomingHash)) {
      await this.compromiseFamily(family.familyId, family.userId)
      throw new AuthError('TOKEN_REUSE_DETECTED')
    }

    // Família já foi marcada como comprometida
    if (family.isCompromised) {
      throw new AuthError('FAMILY_COMPROMISED')
    }

    // Família expirou
    if (family.expiresAt < new Date()) {
      await db.tokenFamily.delete({ where: { familyId: family.familyId } })
      throw new AuthError('TOKEN_EXPIRED')
    }

    // ✅ Token válido → rotation
    return this.generateTokenPair(family.userId, family.familyId)
  }

  // ── comprometer família inteira ──────────────────────────────────────────

  private async compromiseFamily(familyId: string, userId: string) {
    await db.tokenFamily.update({
      where: { familyId },
      data:  { isCompromised: true }
    })

    // Notificar utilizador
    await this.notifySecurityEvent(userId, {
      type:    'SESSION_HIJACK_DETECTED',
      message: 'Sessão inválida detectada. Todas as sessões foram terminadas.',
    })

    // Opcional: invalidar TODAS as famílias do utilizador
    // (resposta mais agressiva, melhor para contas de alto risco)
    await db.tokenFamily.updateMany({
      where: { userId },
      data:  { isCompromised: true }
    })
  }

  private hash(token: string): string {
    return crypto.createHash('sha256').update(token).digest('hex')
  }
}
```

```typescript
// ─── auth controller ─────────────────────────────────────────────────────────

import { Response, Request } from 'express'

const COOKIE_OPTIONS = {
  httpOnly:  true,                              // ← JS não consegue ler
  secure:    process.env.NODE_ENV === 'production', // ← só HTTPS
  sameSite:  'strict' as const,                // ← protecção CSRF base
  path:      '/auth/refresh',                  // ← cookie só vai neste path
  maxAge:    7 * 24 * 60 * 60 * 1000,          // 7 dias em ms
} satisfies CookieOptions

export class AuthController {

  async login(req: Request, res: Response) {
    const { email, password } = req.body

    const user = await userService.validateCredentials(email, password)
    if (!user) {
      // Timing-safe: mesmo delay para user inexistente e password errada
      await constantTimeDelay(200)
      return res.status(401).json({ error: 'INVALID_CREDENTIALS' })
    }

    const { accessToken, refreshToken } = await tokenService.generateTokenPair(
      user.id,
      null // nova família
    )

    // Refresh token → cookie HttpOnly (nunca no body)
    res.cookie('refresh_token', refreshToken, COOKIE_OPTIONS)

    // Access token → body (cliente guarda em memória)
    return res.json({
      accessToken,
      user: { id: user.id, email: user.email, role: user.role }
    })
  }

  async refresh(req: Request, res: Response) {
    const incomingToken = req.cookies['refresh_token']

    if (!incomingToken) {
      return res.status(401).json({ error: 'NO_REFRESH_TOKEN' })
    }

    try {
      const { accessToken, refreshToken, userId } =
        await tokenService.rotateRefreshToken(incomingToken)

      // Novo refresh token substitui o anterior no cookie
      res.cookie('refresh_token', refreshToken, COOKIE_OPTIONS)

      return res.json({ accessToken })

    } catch (err) {
      if (err instanceof AuthError && err.code === 'TOKEN_REUSE_DETECTED') {
        // Limpar cookie comprometido
        res.clearCookie('refresh_token', { path: '/auth/refresh' })
        return res.status(401).json({ error: 'SESSION_COMPROMISED' })
      }
      throw err
    }
  }

  async logout(req: Request, res: Response) {
    const token = req.cookies['refresh_token']

    if (token) {
      // Invalidar família no servidor
      const hash   = tokenService.hash(token)
      const family = await db.tokenFamily.findFirst({
        where: { currentToken: hash }
      })
      if (family) {
        await db.tokenFamily.delete({ where: { familyId: family.familyId } })
      }
    }

    res.clearCookie('refresh_token', { path: '/auth/refresh' })
    return res.json({ ok: true })
  }
}
