```typescript
// ─── axios instance com interceptors ─────────────────────────────────────────

import axios, { AxiosInstance } from 'axios'

let isRefreshing        = false
let refreshSubscribers: Array<(token: string) => void> = []

function subscribeToRefresh(cb: (token: string) => void) {
  refreshSubscribers.push(cb)
}

function notifySubscribers(token: string) {
  refreshSubscribers.forEach(cb => cb(token))
  refreshSubscribers = []
}

export const apiClient: AxiosInstance = axios.create({
  baseURL:         process.env.NEXT_PUBLIC_API_URL,
  withCredentials: true, // ← envia cookies HttpOnly automaticamente
})

// ── request: injectar access token ──────────────────────────────────────────

apiClient.interceptors.request.use(config => {
  const token = authStore.getToken()
  if (token) {
    config.headers.Authorization = `Bearer ${token}`
  }
  return config
})

// ── response: refresh automático em 401 ─────────────────────────────────────

apiClient.interceptors.response.use(
  response => response,

  async error => {
    const originalRequest = error.config

    if (error.response?.status !== 401 || originalRequest._retry) {
      return Promise.reject(error)
    }

    // Evitar múltiplos refreshes em paralelo
    if (isRefreshing) {
      return new Promise(resolve => {
        subscribeToRefresh(token => {
          originalRequest.headers.Authorization = `Bearer ${token}`
          resolve(apiClient(originalRequest))
        })
      })
    }

    originalRequest._retry = true
    isRefreshing           = true

    try {
      // Cookie HttpOnly é enviado automaticamente pelo browser
      const { data } = await axios.post(
        `${process.env.NEXT_PUBLIC_API_URL}/auth/refresh`,
        {},
        { withCredentials: true }
      )

      const newToken = data.accessToken
      authStore.setToken(newToken)
      notifySubscribers(newToken)

      originalRequest.headers.Authorization = `Bearer ${newToken}`
      return apiClient(originalRequest)

    } catch (refreshError) {
      // Refresh falhou → logout forçado
      authStore.clearToken()
      window.location.href = '/login?reason=session_expired'
      return Promise.reject(refreshError)

    } finally {
      isRefreshing = false
    }
  }
)
```

