// ─── inicialização: silent refresh no arranque da app ────────────────────────

// Problema: ao recarregar a página, o accessToken em memória perde-se
// Solução: tentar refresh silencioso antes de renderizar

export async function initializeAuth(): Promise<User | null> {
  try {
    // Se houver cookie válido, isto devolve novo accessToken
    const { data } = await axios.post(
      `${process.env.NEXT_PUBLIC_API_URL}/auth/refresh`,
      {},
      { withCredentials: true }
    )

    authStore.setToken(data.accessToken)
    return data.user

  } catch {
    // Sem sessão válida — utilizador não autenticado
    return null
  }
}

// Em Next.js, por exemplo:
// app/layout.tsx → chama initializeAuth() antes de renderizar
