## Versão Corrigida (referência)

```typescript
// ✅ VERSÃO CORRIGIDA

// 1. Tipos seguros
interface ParallaxConfig {
  speed: number;      // validado: entre -1 e 1
  easing: number;     // lerp factor: 0.05 - 0.15
  direction: 'vertical' | 'horizontal';
}

class ParallaxController {
  private elements: Map<Element, ParallaxConfig> = new Map();
  private rafId: number | null = null;
  private currentY = 0;
  private targetY = 0;
  private observer: IntersectionObserver;
  private activeElements: Set<Element> = new Set();

  constructor() {
    // ✅ Respeita preferências de acessibilidade
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      return;
    }

    this.observer = new IntersectionObserver(
      this.handleIntersection.bind(this),
      { rootMargin: '50px' }
    );

    // ✅ passive: true — não bloqueia scroll thread
    window.addEventListener('scroll', this.onScroll.bind(this), {
      passive: true
    });

    this.tick();
  }

  register(element: Element, config: Partial<ParallaxConfig> = {}) {
    // ✅ Validação e sanitização de inputs
    const safeConfig: ParallaxConfig = {
      speed: this.clamp(Number(config.speed) || 0.3, -1, 1),
      easing: this.clamp(Number(config.easing) || 0.08, 0.01, 1),
      direction: config.direction === 'horizontal' ? 'horizontal' : 'vertical',
    };

    // ✅ Guarda referências — sem querySelectorAll em cada frame
    this.elements.set(element, safeConfig);
    this.observer.observe(element);
  }

  private onScroll() {
    // ✅ Apenas lê — não escreve (sem layout thrashing)
    this.targetY = window.scrollY;
  }

  private tick() {
    // ✅ requestAnimationFrame — sincronizado com o browser
    this.rafId = requestAnimationFrame(this.tick.bind(this));

    // ✅ Lerp easing — suaviza o movimento
    this.currentY += (this.targetY - this.currentY) * 0.08;

    // ✅ Só processa elementos visíveis
    this.activeElements.forEach(el => {
      const config = this.elements.get(el)!;
      const offset = this.currentY * config.speed;

      // ✅ transform — compositor only, zero reflow
      // ✅ translateZ(0) — força GPU layer
      (el as HTMLElement).style.transform =
        `translateY(${offset.toFixed(2)}px) translateZ(0)`;
    });
  }

  private handleIntersection(entries: IntersectionObserverEntry[]) {
    entries.forEach(entry => {
      // ✅ Pausa animação fora do viewport
      if (entry.isIntersecting) {
        this.activeElements.add(entry.target);
      } else {
        this.activeElements.delete(entry.target);
      }
    });
  }

  // ✅ Previne valores extremos / NaN
  private clamp(value: number, min: number, max: number): number {
    if (!isFinite(value)) return min;
    return Math.min(Math.max(value, min), max);
  }

  // ✅ Cleanup — sem memory leaks
  destroy() {
    if (this.rafId) cancelAnimationFrame(this.rafId);
    window.removeEventListener('scroll', this.onScroll.bind(this));
    this.observer.disconnect();
    this.elements.clear();
    this.activeElements.clear();
  }
}
```

