/* ✅ will-change — hint ao browser para criar layer */
[data-parallax] {
  will-change: transform;

  /* ✅ Fallback para reduced-motion */
  @media (prefers-reduced-motion: reduce) {
    will-change: auto;
    transform: none !important;
  }
}

/* ✅ Evita will-change em demasiados elementos (memory) */
[data-parallax]:not(.is-visible) {
  will-change: auto;
}
